#nullable enable // autogenerated

using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Enemies;
using MVZ2.GameContent.Buffs.Enemies;
using PVZEngine.Buffs;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 舞王僵尸：出场冲刺到位（或撞到器械）后召唤伴舞并跳舞，
    /// 之后每走一格所需的时间就再跳一次。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.dancingZombie)]
    public class DancingZombie : AIEntityBehaviour
    {
        // 构造函数：引擎创建这个“行为”时会调用它。
        // nsp / name 是这个敌人注册时用的名字，直接交给父类就好。
        public DancingZombie(string nsp, string name) : base(nsp, name)
        {
        }

        /// <summary>
        /// Init = 初始化。僵尸刚出现在场上时，只调用一次。
        /// 这里给它把各种“数据”准备好。
        /// </summary>
        public override void Init(Entity entity)
        {
            base.Init(entity);

            // FrameTimer 是一个“倒计时器”：
            // 每帧调用一次 Run()，数字就减 1；减到 0 时 Expired 会变成 true。

            // 1) 跳舞计时器：现在还没跳舞，所以设为 null（空）
            SetDanceTimer(entity, null);
            // 2) 行走间隔计时器：走满一格所需的时间到点就跳舞。
            //    出场冲刺阶段不计时，第一次跳舞结束后才开始。
            SetStepTimer(entity, null);
            // 3) 阶段：从“出场冲刺”开始
            SetStage(entity, STAGE_INTRO);
            // 4) 队伍速度：出场冲刺用 2 倍速，第一次跳舞结束后会降到行进速度
            SetBaseSpeed(entity, INTRO_SPEED);

            // 登场 BGM：走循环音效轨道，不影响关卡音乐；多只舞王只共用一个音轨
            if (!entity.IsPreviewEnemy())
            {
                entity.Level.AddLoopSoundEntity(VanillaSoundID.dancingZombieBgm, entity.ID);
            }
        }

        /// <summary>
        /// UpdateAI 每帧都会调用一次，相当于僵尸的“大脑”，
        /// 由它决定这一帧要干什么。
        /// 这里分成三个阶段：登场 → 跳舞 → 走路。
        /// </summary>
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);

            // 死了就什么都不做
            if (entity.IsDead)
                return;

            // ---------- 阶段一：出场冲刺 ----------
            // 以 2 倍速向左冲，两种情况会停下：冲到目标位置，或撞到器械。
            // 停下的当帧就召唤伴舞、开始第一次跳舞。
            // 僵尸模式里如果出生点已在目标位置或更靠左，冲刺当帧就结束。
            if (GetStage(entity) == STAGE_INTRO && GetDanceTimer(entity) == null)
            {
                ApplySpeed(entity, INTRO_SPEED); // 冲刺速度每帧都设一次，防止被随机速度 buff 干扰

                // 撞到器械：引擎会把它切成“啃食”状态。看到啃食 = 撞到了，立刻停下跳舞
                if (entity.State == STATE_MELEE_ATTACK)
                {
                    StartFirstDance(entity);
                    return;
                }

                // 冲到目标位置（从右往左第 3 格的中心）
                if (entity.Position.x <= GetIntroTargetX(entity))
                {
                    StartFirstDance(entity);
                    return;
                }
                return; // 还在冲刺，这一帧不往下走
            }

            // ---------- 不管在哪个阶段，都要维护伴舞 ----------
            // 让伴舞和舞王保持队形、速度一致
            UpdateDancers(entity);

            // ---------- 阶段二：正在跳舞 ----------
            // 跳舞时站着不动，只等跳舞计时结束。
            // 结束后：清计时器、退出跳舞状态、把被打掉的伴舞补召回来。
            var danceTimer = GetDanceTimer(entity);
            if (danceTimer != null)
            {
                danceTimer.Run();
                if (danceTimer.Expired)
                {
                    SetDanceTimer(entity, null);
                    EndDance(entity);
                    // 跳舞过程中被玩家打掉的伴舞，要在跳舞结束后补上
                    SummonDancers(entity);
                    // 第一次跳舞结束：进入行进阶段，全队速度降到 1.5 倍
                    if (GetStage(entity) == STAGE_INTRO)
                    {
                        SetStage(entity, STAGE_MARCH);
                        SetBaseSpeed(entity, MARCH_SPEED);
                    }
                }
                return; // 处理完跳舞，这一帧就不再往下走了
            }

            // ---------- 阶段三：走路 ----------
            // 行走间隔计时器无论在走路、啃食还是受击时都照常走。
            // 走满一格所需的时间到点，就跳一次舞。
            var stepTimer = GetStepTimer(entity);
            if (stepTimer == null)
            {
                stepTimer = new FrameTimer(GetStepInterval(entity));
                SetStepTimer(entity, stepTimer);
            }
            if (stepTimer.RunToExpiredAndNotNull())
            {
                SetStepTimer(entity, null);
                StartDance(entity);
            }
        }

        /// <summary>
        /// 走一格所需的帧数。速度越快，间隔越短。
        /// </summary>
        public static int GetStepInterval(Entity entity)
        {
            var gridWidth = entity.Level.GetGridWidth();
            var walkVelocity = Mathf.Abs(entity.GetSpeed()) * VanillaEnemyExt.WALK_SPEED_FACTOR;
            if (walkVelocity <= 0)
                return 1;
            var frames = Mathf.RoundToInt(gridWidth / walkVelocity * DANCE_INTERVAL_GRIDS);
            return Mathf.Max(1, frames);
        }

        /// <summary>
        /// 管理伴舞：速度同步、落后加速、掉队解绑。
        /// 每帧调用一次。
        /// </summary>
        private void UpdateDancers(Entity entity)
        {
            var level = entity.Level;
            var facingX = entity.GetFacingX();    // 前进方向：1 = 向右，-1 = 向左
            var gridWidth = level.GetGridWidth(); // 一个格子的宽度（游戏里的基本距离单位）

            // 第一步：找出整队里“最慢”的速度。
            // 先假设舞王自己最慢，再看每个伴舞，谁更慢就用谁的。
            var minSpeed = GetBaseSpeed(entity);
            for (int i = 0; i < DANCER_SLOTS.Length; i++)
            {
                var dancer = GetDancer(entity, DANCER_SLOTS[i]);
                if (dancer != null)
                {
                    minSpeed = Mathf.Min(minSpeed, BackupDancer.GetBaseSpeed(dancer));
                }
            }

            // 让舞王用这个“最慢速度”走，整队才不会越走越散
            ApplySpeed(entity, minSpeed);

            // 第二步：逐个检查每个伴舞。
            for (int i = 0; i < DANCER_SLOTS.Length; i++)
            {
                var slot = DANCER_SLOTS[i];
                var dancer = GetDancer(entity, slot);

                // 这个位置没有伴舞（没召唤或已死），清空记录，看下一个
                if (dancer == null)
                {
                    ClearDancer(entity, slot);
                    continue;
                }

                // expectedX = 这个伴舞“应该在”的 x 位置。
                // 算法：舞王位置 + 槽位偏移 × 方向 × 格宽
                var expectedX = entity.Position.x + DANCER_SLOT_OFFSETS[i] * facingX * gridWidth;

                // lag = 伴舞实际位置，比它应该在的位置落后了多少。
                // 乘 -facingX 是为了让“向左走”和“向右走”都能用同一套算法。
                var lag = (dancer.Position.x - expectedX) * -facingX;

                // 落后太多（超过 RELEASE_LAG 格）→ 放弃这个伴舞
                if (lag > gridWidth * RELEASE_LAG)
                {
                    ClearDancer(entity, slot);        // 舞王这边忘掉它
                    BackupDancer.ClearLeader(dancer); // 伴舞那边也忘掉舞王
                    continue;                         // 它以后就像普通僵尸一样走
                }

                // 平时用队伍最小速度；落后一点点就加速追上来
                var speed = minSpeed;
                if (lag > gridWidth * CATCHUP_LAG)
                {
                    speed *= CATCHUP_MULTIPLIER;
                }
                ApplySpeed(dancer, speed);
            }
        }

        /// <summary>
        /// 读取某个槽位上记录的伴舞。
        /// 槽位里存的只是一个 ID，这里把 ID 换成真正的僵尸对象。
        /// 找不到、或者伴舞已经死了，就返回 null（表示“没有”）。
        /// </summary>
        private static Entity? GetDancer(Entity entity, VanillaEntityPropertyMeta<EntityID> slot)
        {
            // 先从舞王身上读出这个槽位保存的 ID
            var id = entity.GetBehaviourField<EntityID>(ID, slot);
            // 用 ID 在关卡里找到对应的僵尸（?. 表示 id 为空时跳过，不会报错）
            var dancer = id?.GetEntity(entity.Level);
            // 僵尸不存在或已经死了，都当作没有
            if (dancer == null || !dancer.ExistsAndAlive())
                return null;
            return dancer;
        }

        /// <summary>
        /// 把某个槽位记录的伴舞清空（解除绑定），下次就能召唤新的。
        /// </summary>
        private static void ClearDancer(Entity entity, VanillaEntityPropertyMeta<EntityID> slot)
        {
            entity.SetBehaviourField<EntityID>(ID, slot, null); // 存 null = 表示“没有伴舞”
        }

        /// <summary>
        /// 取出这个僵尸出场时保存的原始速度。
        /// </summary>
        private static float GetBaseSpeed(Entity entity)
        {
            return entity.GetBehaviourField<float>(ID, PROP_BASE_SPEED);
        }

        /// <summary>
        /// 设置僵尸的速度。
        /// 有些敌人带有“随机速度”Buff（会随机快一点或慢一点），
        /// 这里把它固定成 1 倍，避免影响队伍整齐。
        /// </summary>
        private static void ApplySpeed(Entity entity, float speed)
        {
            entity.SetProperty(VanillaEnemyProps.SPEED, speed);
            // GetBuffs 找到这个僵尸身上所有这种 Buff，逐个改成 1 倍
            foreach (var buff in entity.GetBuffs<RandomEnemySpeedBuff>())
            {
                RandomEnemySpeedBuff.SetSpeed(buff, 1);
            }
        }

        /// <summary>
        /// 死亡时调用。
        /// 如果正在跳舞，先结束跳舞；然后停掉这只僵尸的 BGM。
        /// </summary>
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);

            // IsCasting() = 是否正在跳舞。死在跳舞中，要先把跳舞状态关掉
            if (entity.IsCasting())
            {
                EndDance(entity);
            }
            // 关掉这只僵尸的登场 BGM
            entity.Level.RemoveLoopSoundEntity(VanillaSoundID.dancingZombieBgm, entity.ID);
        }

        /// <summary>
        /// 被移出关卡时调用（例如关卡结束）。
        /// </summary>
        public override void PostRemove(Entity entity)
        {
            base.PostRemove(entity);
            // 也要把 BGM 停掉，防止声音一直响
            entity.Level.RemoveLoopSoundEntity(VanillaSoundID.dancingZombieBgm, entity.ID);
        }

        // ============================================================
        // 下面是“读 / 写数据”的小工具方法。
        // C# 里的习惯写法：每个数据配一对 SetXxx / GetXxx。
        //   SetXxx = 把数据存进去；GetXxx = 把数据取出来。
        // 这样别的脚本不用管数据存在哪，调用方法就行。
        // ============================================================
        // ---- 阶段 ----
        // STAGE_INTRO = 出场冲刺；STAGE_MARCH = 第一次跳舞结束后的正常行进。
        public const int STAGE_INTRO = 0;
        public const int STAGE_MARCH = 1;

        public static void SetStage(Entity entity, int stage)
        {
            entity.SetBehaviourField(ID, PROP_STAGE, stage);
        }

        public static int GetStage(Entity entity)
        {
            return entity.GetBehaviourField<int>(ID, PROP_STAGE);
        }

        /// <summary>
        /// 出场冲刺的目标位置：从右往左第 3 格的中心 X。
        /// 冲到这里就停下开始跳舞；出生点已经在目标或更靠左时（比如僵尸模式直接摆放），
        /// 冲刺当帧就结束。
        /// </summary>
        public static float GetIntroTargetX(Entity entity)
        {
            var level = entity.Level;
            // 格子编号从 0 开始，所以“从右往左第 3 格” = 总列数 - 3。
            // 列数不足 3 的关卡就退到第 0 列。
            var column = Mathf.Max(0, level.GetMaxColumnCount() - INTRO_TARGET_COLUMN_FROM_RIGHT);
            return level.GetColumnCenterX(column);
        }

        // ---- 跳舞计时器 ----
        public static void SetDanceTimer(Entity entity, FrameTimer? timer)
        {
            entity.SetBehaviourField(ID, PROP_DANCE_TIMER, timer);
        }

        public static FrameTimer? GetDanceTimer(Entity entity)
        {
            return entity.GetBehaviourField<FrameTimer>(ID, PROP_DANCE_TIMER);
        }

        // ---- 行走间隔计时器（走满一格所需时间）----
        public static void SetStepTimer(Entity entity, FrameTimer? timer)
        {
            entity.SetBehaviourField(ID, PROP_STEP_TIMER, timer);
        }

        public static FrameTimer? GetStepTimer(Entity entity)
        {
            return entity.GetBehaviourField<FrameTimer>(ID, PROP_STEP_TIMER);
        }

        // ---- 出场时的原始速度 ----
        public static void SetBaseSpeed(Entity entity, float value)
        {
            entity.SetBehaviourField(ID, PROP_BASE_SPEED, value);
        }

        /// <summary>
        /// 出场冲刺结束（冲到目标位置或撞到器械）时调用：
        /// 先召唤伴舞，再开始第一次跳舞。
        /// </summary>
        private void StartFirstDance(Entity entity)
        {
            SummonDancers(entity); // 先召唤伴舞
            StartDance(entity);    // 再开始跳舞
        }

        /// <summary>
        /// 开始跳舞：进入跳舞状态、播放音效、开启跳舞计时。
        /// </summary>
        public static void StartDance(Entity entity)
        {
            entity.SetCasting(true);                            // 进入“跳舞”状态（动画和逻辑会用到）
            entity.PlaySound(VanillaSoundID.reviveCast);        // 播放跳舞音效
            SetDanceTimer(entity, new FrameTimer(DANCE_TIME));  // 开始跳舞倒计时
        }

        /// <summary>
        /// 结束跳舞：退出跳舞状态。
        /// </summary>
        public static void EndDance(Entity entity)
        {
            entity.SetCasting(false); // 退出“跳舞”状态
        }

        /// <summary>
        /// 给伴舞用：判断自己 (self) 是不是已经跑到了槽位前面。
        /// 返回 true = 走太快了，该等一等；false = 可以继续走。
        /// </summary>
        public static bool IsAheadOfSlot(Entity self, Entity leader, float offsetX)
        {
            var level = leader.Level;
            var gridWidth = level.GetGridWidth();
            // 算出这个槽位“应该”在的 x 位置
            var expectedX = leader.Position.x + offsetX * leader.GetFacingX() * gridWidth;
            // self 的 x 比预期位置还小（更靠左），说明它已经跑到前面去了
            return self.Position.x < expectedX - gridWidth * WAIT_TOLERANCE;
        }

        /// <summary>
        /// 给舞王用：是否有伴舞掉队太多。
        /// 只要有一个伴舞落后超过 DANCER_WAIT_LAG 格，就返回 true（舞王应该停下等）。
        /// </summary>
        public static bool ShouldWaitForDancers(Entity entity)
        {
            var level = entity.Level;
            var gridWidth = level.GetGridWidth();
            var facingX = entity.GetFacingX();

            // 逐个检查 4 个槽位
            for (int i = 0; i < DANCER_SLOTS.Length; i++)
            {
                var id = entity.GetBehaviourField<EntityID>(ID, DANCER_SLOTS[i]);
                var dancer = id?.GetEntity(level);
                // 没有伴舞，跳过
                if (dancer == null || !dancer.ExistsAndAlive())
                    continue;

                // 算出槽位“应该”在的 x 位置
                var expectedX = entity.Position.x + DANCER_SLOT_OFFSETS[i] * facingX * gridWidth;
                // 伴舞落后超过容许范围 → 需要等待
                if (dancer.Position.x > expectedX + gridWidth * DANCER_WAIT_LAG)
                    return true;
            }
            return false; // 所有伴舞都跟得上
        }

        /// <summary>
        /// 召唤缺少的伴舞。
        /// 规则：某个槽位已经有“活着的、正常走路的”伴舞，就不重复召唤。
        /// </summary>
        private void SummonDancers(Entity entity)
        {
            // 先读出几个常用数据，后面好直接用：
            var level = entity.Level;              // 当前关卡
            var facingX = entity.GetFacingX();     // 前进方向（1 = 右，-1 = 左）
            var gridWidth = level.GetGridWidth();  // 一格有多宽
            var lane = entity.GetLane();           // 舞王在第几行（从上往下数，从 0 开始）
            var maxLane = level.GetMaxLaneCount(); // 关卡一共几行

            // 这是一个“本地函数”：只在这个方法内部能用的小工具。
            // 作用：给某个槽位补一个伴舞（如果缺的话）。
            void SummonIfMissing(
                VanillaEntityPropertyMeta<EntityID> slot,
                Vector3 position,
                float offsetX)
            {
                // 先看这个槽位原来有没有伴舞
                var oldID = entity.GetBehaviourField<EntityID>(ID, slot);
                var oldDancer = oldID?.GetEntity(level);

                // 如果老伴舞还活着，而且没被强制移动（比如没被击退飞走），就不重复召唤
                if (oldDancer != null &&
                    oldDancer.ExistsAndAlive() &&
                    !oldDancer.IsForcedMovement())
                {
                    return;
                }

                // 从空中落下登场：先算地面高度，再往上抬 DROP_HEIGHT
                position.y = level.GetGroundY(position.x, position.z) + DROP_HEIGHT;

                // 在算好的位置生成一个伴舞僵尸
                var dancer = entity.SpawnWithParams(
                    VanillaEnemyID.backupDancer,
                    position);

                // 生成失败（返回 null）就直接结束
                if (dancer == null)
                    return;

                // 从高空落下时免疫摔落伤害
                dancer.SetProperty(
                    VanillaEntityProps.FALL_RESISTANCE,
                    NO_FALL_DAMAGE_RESISTANCE);

                // 告诉伴舞：你的“队长”是这只舞王，你的槽位偏移是 offsetX
                BackupDancer.Setup(dancer, new EntityID(entity), offsetX);
                // 伴舞的“原始速度”要和舞王当前的速度一致。
                // 不然队伍取最小速度时会被伴舞自带的默认速度（1）拖慢。
                BackupDancer.SetBaseSpeed(dancer, GetBaseSpeed(entity));

                // 把新伴舞的 ID 记到舞王的槽位上，之后就能一直找到它
                entity.SetBehaviourField(
                    ID,
                    slot,
                    new EntityID(dancer));
            }

            for (int i = 0; i < DANCER_SLOTS.Length; i++)
            {
                // 这个槽位应该在舞王的第几行
                var targetLane = lane + DANCER_SLOT_ROW_OFFSETS[i];
                // 如果算出来的行超出地图（比如舞王在最上面一行，还要往上召唤），就跳过。
                // 这就是“只召唤 3 个”的原因：边路的那个槽位会被跳过。
                if (targetLane < 0 || targetLane >= maxLane)
                    continue;

                var offsetX = DANCER_SLOT_OFFSETS[i];
                // 从舞王的位置出发，算出这个槽位在世界里的坐标
                var position = entity.Position;
                position.x += gridWidth * offsetX * facingX;  // 左右方向偏移
                position.z = level.GetEntityLaneZ(targetLane); // 上下方向（行）偏移

                SummonIfMissing(DANCER_SLOTS[i], position, offsetX);
            }
        }

        #region 常量
        // 这个区域集中放着所有“不会变的数字”。
        // 想调整游戏手感，基本只需要改这里的数字。

        // 出场冲刺的速度倍率（普通僵尸的移速是 1）
        private const float INTRO_SPEED = 2f;
        // 冲完之后的行进速度倍率
        private const float MARCH_SPEED = 1.5f;
        // 出场冲刺目标：从右往左数第几格（1 = 最右边那格）
        private const int INTRO_TARGET_COLUMN_FROM_RIGHT = 3;
        // 每次跳舞持续多少帧
        private const int DANCE_TIME = 45;
        // 跳舞间隔 = 走多少格所需的时间（1 = 每走一格的时间跳一次）
        private const float DANCE_INTERVAL_GRIDS = 1f;

        // 以下数值都以“格子宽度”为单位
        // 判断伴舞是否已经到达槽位的容差
        public const float WAIT_TOLERANCE = 0.05f;
        // 伴舞落后超过这个距离，舞王就停下等它
        public const float DANCER_WAIT_LAG = 0.05f;
        // 伴舞落后超过这个距离，就开始加速追赶
        public const float CATCHUP_LAG = 0.05f;
        // 追赶时，速度要乘这个倍率
        public const float CATCHUP_MULTIPLIER = 1.4f;
        // 伴舞落后超过这个距离，就彻底解绑（变成普通僵尸）
        public const float RELEASE_LAG = 2f;

        // 登场 BGM 的音量
        public const float BGM_VOLUME = 1.2f;

        // 伴舞出场的离地高度（16 倍僵尸身高 86 ≈ 1376）
        public const float DROP_HEIGHT = 1376f;
        // 摔落抗性：远大于下落速度，等于完全免摔落伤害
        public const float NO_FALL_DAMAGE_RESISTANCE = 10000f;

        // 僵尸状态编号（直接沿用游戏引擎定义好的）
        public const int STATE_MELEE_ATTACK = LogicEnemyStates.MELEE_ATTACK;
        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int STATE_CAST = LogicEnemyStates.CAST;

        // 这个敌人的唯一 ID
        public static readonly NamespaceID ID = VanillaEnemyID.dancingZombie;

        // 下面是“行为字段”的声明，相当于给舞王准备几个带名字的小抽屉：
        //   PROP_XXX 就是抽屉的钥匙，前面的 Set/Get 方法用这把钥匙存取数据。
        public static readonly VanillaEntityPropertyMeta<int> PROP_STAGE = new VanillaEntityPropertyMeta<int>("Stage");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_DANCE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("DanceTimer");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STEP_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("StepTimer");
        public static readonly VanillaEntityPropertyMeta<float> PROP_BASE_SPEED = new VanillaEntityPropertyMeta<float>("BaseSpeed");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_FRONT_DANCER = new VanillaEntityPropertyMeta<EntityID>("front_dancer");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_BACK_DANCER = new VanillaEntityPropertyMeta<EntityID>("back_dancer");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_UPPER_DANCER = new VanillaEntityPropertyMeta<EntityID>("upper_dancer");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_LOWER_DANCER = new VanillaEntityPropertyMeta<EntityID>("lower_dancer");
        // 4 个伴舞槽位：前、后、上、下。
        // 数组顺序很重要，要和下面两个偏移数组一一对应。
        public static readonly VanillaEntityPropertyMeta<EntityID>[] DANCER_SLOTS = new VanillaEntityPropertyMeta<EntityID>[]
        {
            PROP_FRONT_DANCER,
            PROP_BACK_DANCER,
            PROP_UPPER_DANCER,
            PROP_LOWER_DANCER,
        };
        /// <summary>
        /// 各槽位相对舞王的横向偏移（单位：格，正数为前进方向）。
        /// 例如：前 = +1 格（往前走一格），后 = -1 格（往后退一格）。
        /// </summary>
        public static readonly float[] DANCER_SLOT_OFFSETS = new float[]
        {
            1f,   // 前
            -1f,  // 后
            0f,   // 上
            0f,   // 下
        };
        /// <summary>
        /// 各槽位相对舞王的行偏移（lane 0 在最上方，lane 越大越靠下）。
        /// 例如：上 = -1 行（往上一行），下 = +1 行（往下一行）。
        /// </summary>
        public static readonly int[] DANCER_SLOT_ROW_OFFSETS = new int[]
        {
            0,   // 前
            0,   // 后
            -1,  // 上
            1,   // 下
        };
        #endregion 常量
    }
}